(()=>{
const key='etohcols-cart-v1',allowedSizes=['1L','5L','20L','200L','1000L','ISO Tank'];
const allowedSkus=['etoh','pharmol'].flatMap(b=>(b==='pharmol'?['95','96','99-9']:['70','75','95','96','99-9']).map(p=>`${b}-${p}`));
const valid=i=>i&&allowedSkus.includes(i.sku)&&allowedSizes.includes(i.size)&&Number.isInteger(i.quantity)&&i.quantity>0&&i.quantity<=100000;
let cart=[];try{const data=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(data))cart=data.filter(valid).map(({sku,size,quantity})=>({sku,size,quantity}));}catch{}
const name=i=>(i.sku.startsWith('pharmol')?'Pharmol':'Etoh')+' '+i.sku.replace(/^(?:pharmol|etoh)-/,'').replace('-', '.')+'%';
const size=i=>i.size==='1000L'?'IBC Tank 1,000 ลิตร':i.size==='ISO Tank'?'ISO Tank':i.size.replace('L',' ลิตร');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sum=()=>cart.reduce((n,i)=>n+i.quantity,0);
function status(message){let box=document.querySelector('#cart-status');if(!box){box=document.createElement('div');box.id='cart-status';box.className='cart-status';box.setAttribute('role','status');document.body.append(box);}box.textContent=message;clearTimeout(status.timer);status.timer=setTimeout(()=>box.remove(),4000);}
function save(){try{localStorage.setItem(key,JSON.stringify(cart));}catch{status('เบราว์เซอร์ไม่อนุญาตให้เก็บตะกร้า รายการอาจหายเมื่อเปลี่ยนหน้า');}updateCount();}
function updateCount(){document.querySelectorAll('[data-cart-count]').forEach(e=>e.textContent=String(cart.length));}
const empty=()=>'<div class="empty-cart"><span>＋</span><h2>ตะกร้ายังว่าง</h2><p>เลือกสินค้าและขนาดที่ต้องการ แล้วเพิ่มรายการเพื่อขอราคาหรือสั่งซื้อ</p><a class="btn" href="/shop/">เลือกสินค้า ↗</a></div>';
function summary(){return cart.map(i=>`<div class="summary-item"><div><strong>${esc(name(i))}</strong><small>${size(i)} × ${i.quantity}</small></div><span>รอยืนยันราคา</span></div>`).join('')+'<div class="summary-total"><span>ยอดรวม / ค่าขนส่ง / ภาษี</span><strong>รอยืนยัน</strong></div><p class="fine-print">ยังไม่ใช่ยอดที่ต้องชำระ</p>';}
function renderCart(){const el=document.querySelector('#cart-page');if(!el)return;if(!cart.length){el.innerHTML=empty();return;}el.innerHTML=`<div class="cart-layout"><div class="cart-lines">${cart.map((i,index)=>`<article class="cart-line"><div class="cart-token">${i.sku.startsWith('pharmol')?'PH':'ET'}</div><div class="cart-description"><a href="/product/${i.sku}/?size=${encodeURIComponent(i.size)}"><h3>${esc(name(i))}</h3></a><p>ขนาด ${size(i)}</p><button type="button" class="remove-item" data-remove="${index}">นำออก</button></div><label>จำนวน<input type="number" min="1" max="100000" step="1" value="${i.quantity}" data-quantity="${index}" aria-label="จำนวน ${esc(name(i))} ${size(i)}"></label><span class="price-pending">รอยืนยันราคา</span></article>`).join('')}</div><aside class="cart-aside"><h2>สรุปรายการ</h2><p>${cart.length} รายการ · ${sum()} บรรจุภัณฑ์</p><div class="summary-total"><span>ยอดรวม</span><strong>รอยืนยันราคา</strong></div><a class="btn" href="/checkout/">ดำเนินการสั่งซื้อ ↗</a><a class="btn btn-outline" href="/quote/?cart=1">ขอใบเสนอราคาทั้งตะกร้า ↗</a><p class="fine-print">รายการในตะกร้ายังไม่เป็นการจองสินค้า</p></aside></div>`;}
document.addEventListener('click',e=>{const add=e.target.closest('[data-add-cart]');if(add){const sku=add.dataset.addCart;const selected=document.querySelector('#detail-size');const selectedQty=document.querySelector('#buy-quantity');const quantity=selectedQty?Number(selectedQty.value):1;const chosen=selected?.value||add.dataset.size||'200L';const item={sku,size:chosen,quantity};if(!valid(item)){selectedQty?.reportValidity();status('กรุณาระบุจำนวนเต็มระหว่าง 1 ถึง 100000');return;}const existing=cart.find(i=>i.sku===sku&&i.size===chosen);if(existing){if(existing.quantity+quantity>100000){status('จำนวนรวมสูงเกินกำหนด กรุณาติดต่อทีมงาน');return;}existing.quantity+=quantity;}else cart.push(item);save();status(`เพิ่ม ${name(item)} ${size(item)} ลงตะกร้าแล้ว`);return;}const remove=e.target.closest('[data-remove]');if(remove){cart.splice(Number(remove.dataset.remove),1);save();renderCart();}});
document.addEventListener('change',e=>{if(e.target.matches('[data-quantity]')){const n=Number(e.target.value),i=Number(e.target.dataset.quantity);if(!Number.isInteger(n)||n<1||n>100000){e.target.reportValidity();e.target.value=cart[i].quantity;return;}cart[i].quantity=n;save();renderCart();}});
const quote=document.querySelector('.quote-form');if(quote&&new URLSearchParams(location.search).get('cart')==='1'){if(cart.length){quote.elements.namedItem('product').value='ขอคำแนะนำ';quote.elements.namedItem('size').value='ขอคำแนะนำ';quote.elements.namedItem('quantity').value=sum();quote.elements.namedItem('note').value='ขอใบเสนอราคารายการในตะกร้า\n'+cart.map(i=>`${name(i)} | ${size(i)} | จำนวน ${i.quantity}`).join('\n');const info=document.createElement('div');info.className='quote-cart-summary';info.innerHTML='<h3>รายการที่ขอราคา</h3>'+summary();quote.prepend(info);}else{const info=document.createElement('p');info.textContent='ตะกร้ายังว่าง คุณสามารถเลือกสินค้าในแบบฟอร์มนี้ได้';quote.prepend(info);}}
const checkout=document.querySelector('#checkout-form');if(checkout){if(!cart.length){document.querySelector('#checkout-content').hidden=true;const emptyBox=document.querySelector('#checkout-empty');emptyBox.hidden=false;emptyBox.innerHTML=empty();}else document.querySelector('#checkout-summary').innerHTML=summary();document.querySelector('#invoice-needed').addEventListener('change',e=>{document.querySelector('#invoice-fields').hidden=!e.target.checked;for(const id of ['tax-company','tax-id','tax-address']){document.getElementById(id).required=e.target.checked;document.getElementById(id).disabled=!e.target.checked;}});for(const id of ['tax-company','tax-id','tax-address'])document.getElementById(id).disabled=true;let orderData=null;const lines=()=>cart.map(i=>`${name(i)} / ${size(i)} / จำนวน ${i.quantity}`).join('\n');const text=()=>`คำสั่งซื้อตัวอย่าง ETOH COLS (ยังไม่ส่งข้อมูล)\n${lines()}\nชื่อ: ${orderData['order-name']}\nบริษัท: ${orderData['order-company']||'-'}\nโทร: ${orderData['order-phone']}\nอีเมล: ${orderData['order-email']||'-'}\nที่อยู่: ${orderData.address} ${orderData['order-province']} ${orderData['order-postcode']}\nรายละเอียด: ${orderData.note||'-'}\n${orderData.invoice?'ข้อมูลเอกสาร: '+orderData['tax-company']+' / '+orderData['tax-id']+' / '+orderData['tax-address']+'\n':''}ยอดสินค้า ค่าขนส่ง และภาษี: รอยืนยันจากทีมขาย`;
checkout.addEventListener('submit',e=>{e.preventDefault();if(!checkout.reportValidity())return;orderData=Object.fromEntries(new FormData(checkout));document.querySelector('#checkout-content').hidden=true;const review=document.querySelector('#order-review');review.hidden=false;review.innerHTML='<h2>ตรวจคำสั่งซื้อของคุณ</h2>'+summary()+`<div class="review-address"><h3>ผู้ติดต่อและปลายทาง</h3><p>${esc(orderData['order-name'])} · ${esc(orderData['order-phone'])}</p><p>${esc(orderData.address)}<br>${esc(orderData['order-province'])} ${esc(orderData['order-postcode'])}</p>${orderData.invoice?`<p>ข้อมูลออกเอกสาร: ${esc(orderData['tax-company'])}<br>${esc(orderData['tax-id'])}<br>${esc(orderData['tax-address'])}</p>`:''}</div><div class="actions"><button class="btn" id="confirm-demo" type="button">สร้างคำสั่งซื้อตัวอย่าง</button><button class="btn btn-outline" id="edit-order" type="button">แก้ไขข้อมูล</button></div><p class="fine-print">ปุ่มนี้ใช้ทดลองหน้าจอเท่านั้น ไม่ส่งคำสั่งซื้อให้บริษัทและไม่เรียกเก็บเงิน</p>`;review.scrollIntoView({behavior:'smooth',block:'start'});document.querySelector('#edit-order').onclick=()=>{review.hidden=true;document.querySelector('#checkout-content').hidden=false;checkout.scrollIntoView({behavior:'smooth'});};document.querySelector('#confirm-demo').onclick=()=>{review.hidden=true;const result=document.querySelector('#order-result');result.hidden=false;result.innerHTML='<div class="success-mark">✓</div><div class="eyebrow">ORDER PREVIEW</div><h2>คำสั่งซื้อตัวอย่างพร้อมแล้ว</h2><p>ยังไม่ได้ส่งข้อมูลให้ทีมงาน และยังไม่มีการยืนยันราคา สต็อก หรือคำสั่งซื้อจริง</p><pre></pre><div class="actions"><button class="btn" id="copy-order" type="button">คัดลอกรายการ</button><a class="btn btn-outline" href="/cart/">กลับไปตะกร้า ↗</a></div>';result.querySelector('pre').textContent=text();document.querySelector('#copy-order').onclick=async()=>{try{await navigator.clipboard.writeText(text());document.querySelector('#copy-order').textContent='คัดลอกแล้ว ✓';}catch{status('กรุณาเลือกข้อความเพื่อคัดลอก');}};result.scrollIntoView({behavior:'smooth',block:'start'});};});}
window.addEventListener('storage',e=>{if(e.key===key)location.reload();});updateCount();renderCart();
})();
